import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../../../Core/Utils/Widget/custom_scaffold_messenger.dart';import '../../../../../../Config/app_config.dart';import '../../../../../../Core/Resources/app_colors.dart';import '../../../../../../Core/Resources/app_fonts.dart';import '../../../../../../Core/Utils/Widget/TextField/build_text_field.dart';import '../../../../../../Core/Utils/Widget/default_app_bar.dart';import '../../../../../../Core/Utils/Widget/loading_animation.dart';import '../../../../../Global/Authentication/presentation/components/build_social_login_button.dart';import '../../domain/repositories/cart_repo_impl.dart';import '../../domain/useCases/cart_use_case.dart';import '../Cubit/Cart/cart_state.dart';import '../../../../../../Core/Utils/Extensions/localizations_extension.dart';import '../Cubit/Cart/cart_cubit.dart';import '../widgets/body_page_cart_items.dart';import '../widgets/no_item.dart';final TextEditingController textCoupon = TextEditingController();class CartScreen extends StatelessWidget {  const CartScreen({super.key});  @override  Widget build(BuildContext context) {    final local = context.local;    return BlocProvider(      create: (context) => CartCubit(        GetCartUseCase(          CartRepoImpl(),        ),        UpdateCartUseCase(          CartRepoImpl(),        ),        RemoveItemUseCase(          CartRepoImpl(),        ),      )..initItems(),      child: BlocConsumer<CartCubit, CartStates>(      listener: (context, state) {        if (state.success == false) {          showCustomSnackBar(context, state.error.toString(), SnackBarType.error);        }      },        builder: (context, state) {          return Scaffold(            appBar: DefaultAppBar(local: local),            body: state.loading == true                ? CustomLoadingAnimation()                : state.loading == null                    ? NoItemsCart(local: local)                    :  BodyPageCartItems(                            cartItems: state.cartItems?.cartItems ?? [],                            local: local,                          ),            persistentFooterButtons: [              Align(                child: Padding(                  padding:  EdgeInsets.symmetric(horizontal:AppConfig.customPaddingFromRightLeft),                  child: Column(                  children: [                    DefaultTextFormField(                      isTextOut: false,                      text: local.PromoCode,                      type: TextInputType.none,                      controller: textCoupon,                      onChanged: (value) {                      },                    ),                    Row(                      mainAxisAlignment: MainAxisAlignment.spaceBetween,                      children: [                        Text(                          local.Subtotal,                          style: AppTextStyles.h5Bold,                        ),                        Text(                          '${state.cartItems?.summary?.subtotal ?? 0}',                          style: AppTextStyles.h5Bold,                        ),                      ],                    ),                    Row(                      mainAxisAlignment: MainAxisAlignment.spaceBetween,                      children: [                        Text(                          local.DeliveryCharge,                          style: AppTextStyles.h5Bold,                        ),                        Text(                          '${state.cartItems?.summary?.deliveryCharge ?? 0}',                          style: AppTextStyles.h5Bold,                        ),                      ],                    ),                    25.verticalSpace,                    Divider(                      thickness: 1,                      color: AppColors.grayscale50,                    ),                    Row(                      mainAxisAlignment: MainAxisAlignment.spaceBetween,                      children: [                        Text(                          local.TotalAmount,                          style: AppTextStyles.h5Bold,                        ),                        Text(                          '${state.cartItems?.summary?.grandTotal ?? 0}',                          style: AppTextStyles.h5Bold,                        ),                      ],                    ),                    10.verticalSpace,                    BuildSocialLoginButton(                      size: Size(.8.sw, 56.h),                      text: context.local.BuyNow,                      textStyle: AppTextStyles.h5Bold.copyWith(                        color: AppColors.textColorWhite,                      ),                      isSpace: false,                      backgroundColor: AppColors.primaryColor,                      onPressed: () {},                    )                  ],                ),                ),              )            ],          );        },      ),    );  }}